<script setup>
import {ref,computed,onUnmounted,nextTick} from 'vue';
import LookupAssist from '../components/LookupAssist.vue';
import RegistrationProfile from '../components/RegistrationProfile.vue';
import Icon from '../components/Icon.vue';
import BaseModal from '../components/BaseModal.vue';
import EmptyState from '../components/EmptyState.vue';
import {state,company,api,loadCompanies,activate,notify,ask,changed} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';
import {taxId,normalized} from '../lib/format';
const query=ref(''),regimeFilter=ref(''),show=ref(false),tab=ref('identity'),editing=ref(null),busy=ref(false),error=ref(''),form=ref({});let baseline='';
const regimes={simples_nacional:'Simples Nacional',lucro_presumido:'Lucro Presumido',lucro_real:'Lucro Real',outros:'Outro / a definir'};
const filtered=computed(()=>state.companies.filter(c=>(!regimeFilter.value||c.regime===regimeFilter.value)&&normalized(`${c.code} ${c.name} ${c.trade_name} ${c.tax_id}`).includes(normalized(query.value))));
const tabs=[['identity','Identificação'],['address','Endereço'],['fiscal','Fiscal'],['accounting','Contábil'],['integrations','Integrações']];
const keys=['code','name','trade_name','tax_id','regime','state','city','address','number','district','postal_code','ibge','ie','im','cnae','email','phone','prosoft_code'];
function open(c=null){editing.value=c;form.value=Object.fromEntries(keys.map(k=>[k,c?.[k]??'']));if(!c){form.value.code=String(Math.max(0,...state.companies.map(x=>Number(x.code)||0))+1).padStart(4,'0');form.value.regime='outros';form.value.create_default_accounts=true;}form.value.profile=JSON.parse(JSON.stringify(c?.profile||{ie_status:'unknown',state_registrations:[],secondary_cnaes:[]}));form.value.version=c?.version;baseline=JSON.stringify(form.value);tab.value='identity';error.value='';show.value=true;state.editor={name:'Cadastro de empresa',companyId:c?.id};}
async function close(){if(busy.value)return;if(JSON.stringify(form.value)!==baseline&&!await ask({title:'Descartar alterações?',message:'O cadastro ainda não foi salvo. Você pode voltar à edição ou descartar as alterações.',confirmLabel:'Descartar alterações',danger:true}))return;show.value=false;state.editor=null;}
async function save(makeActive=false){const el=document.getElementById('company-form');if(!el.checkValidity()){tab.value='identity';await nextTick();el.reportValidity();return;}busy.value=true;error.value='';try{const d=await api(editing.value?`/companies/${editing.value.id}`:'/companies',{method:editing.value?'PUT':'POST',body:form.value});await loadCompanies();show.value=false;state.editor=null;changed();if(makeActive)await activate(d.id);notify(editing.value?'Cadastro da empresa atualizado.':'Empresa cadastrada.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function select(c){try{if(await activate(c.id))notify(`${c.trade_name||c.name} é a empresa ativa.`);}catch(e){notify(e.message,'error');}}
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">CADASTROS DO ESCRITÓRIO</div><h1>Empresas</h1><p>Organize os cadastros e escolha em qual empresa trabalhar.</p></div><button class="button primary" v-allow="state.session?.user?.role==='admin'" @click="open()"><Icon name="plus"/>Nova empresa</button></header>
<div class="summary-strip"><div><Icon name="building"/><strong>{{state.companies.length}}</strong><span>empresas cadastradas</span></div><div v-if="company"><span class="dot green"></span><span>Empresa ativa:</span><strong>{{company.code}} · {{company.trade_name||company.name}}</strong></div><div v-else><span class="dot amber"></span><span>Selecione uma empresa para iniciar os lançamentos.</span></div></div>
<section class="panel"><div class="table-toolbar"><div class="search-field"><Icon name="search"/><input v-model="query" placeholder="Pesquisar por código, nome ou CNPJ" aria-label="Pesquisar empresas"/></div><select v-model="regimeFilter" aria-label="Filtrar regime tributário"><option value="">Todos os regimes</option><option v-for="(label,key) in regimes" :key="key" :value="key">{{label}}</option></select><span class="count">{{filtered.length}} empresas</span></div>
<div v-if="filtered.length" class="table-scroll"><table><thead><tr><th>Código</th><th>Empresa</th><th>CNPJ</th><th>Regime tributário</th><th>UF</th><th class="right">Ações</th></tr></thead><tbody><tr v-for="c in filtered" :key="c.id" :class="{'active-row':c.id===state.companyId}"><td class="mono">{{c.code}}</td><td><div class="company-cell"><span class="avatar"><Icon name="building"/></span><div><strong>{{c.trade_name||c.name}}</strong><small>{{c.name}}</small></div><span v-if="c.id===state.companyId" class="badge success">Ativa</span></div></td><td class="mono nowrap">{{taxId(c.tax_id)}}</td><td>{{regimes[c.regime]||c.regime||'A definir'}}</td><td>{{c.state||'—'}}</td><td><div class="actions"><button class="icon-button" v-allow="c.can_edit!==false" @click="open(c)" :aria-label="`Editar empresa ${c.name}`" title="Editar cadastro"><Icon name="edit"/></button><button class="button small" :class="c.id===state.companyId?'muted-button':'outline'" :disabled="c.id===state.companyId||state.contextBusy" @click="select(c)" :aria-label="`Ativar empresa ${c.name}`"><Icon :name="c.id===state.companyId?'check':'arrow'" :size="15"/>{{c.id===state.companyId?'Em uso':'Ativar'}}</button></div></td></tr></tbody></table></div>
<EmptyState v-else title="Nenhuma empresa encontrada" text="Cadastre a primeira empresa ou ajuste sua pesquisa." icon="building"/>
<footer class="table-footer"><span>Ativar uma empresa define o contexto dos lançamentos e relatórios.</span><span>{{filtered.length}} de {{state.companies.length}}</span></footer></section>
<BaseModal v-if="show" :title="editing?'Editar empresa':'Nova empresa'" :subtitle="editing?`${editing.code} · ${editing.name}`:'Um cadastro único para fiscal, contábil e financeiro.'" wide @close="close"><div class="modal-tabs" role="tablist"><button v-for="[id,label] in tabs" :key="id" :class="{selected:tab===id}" @click="tab=id" role="tab" :aria-selected="tab===id">{{label}}</button></div>
<div v-if="error" class="message error" role="alert"><Icon name="alert"/><span>{{error}}</span></div>
<form novalidate id="company-form" @submit.prevent="save(false)" class="form-body">
<div v-show="tab==='identity'"><div class="section-label">Dados da empresa <span>* obrigatórios</span></div><div class="form-grid three"><label>Código *<input v-model="form.code" required maxlength="20" autofocus placeholder="0001"/></label><label class="span-2">Razão social *<input v-model="form.name" required maxlength="180" placeholder="Nome empresarial completo"/></label><label class="span-2">Nome fantasia / apelido<input v-model="form.trade_name" maxlength="120" placeholder="Nome usado no escritório"/></label><label>CNPJ *<input v-model="form.tax_id" required maxlength="18" placeholder="00.000.000/0000-00" style="text-transform:uppercase"/><small>Aceita formato numérico e alfanumérico.</small></label><label>Regime tributário *<select v-model="form.regime" required><option v-for="(label,key) in regimes" :key="key" :value="key">{{label}}</option></select></label><label>E-mail<input v-model="form.email" type="email" placeholder="contato@empresa.com.br"/></label><label>Telefone<input v-model="form.phone" placeholder="(00) 0000-0000"/></label></div><LookupAssist :target="form"/><div class="message subtle"><Icon name="info"/><span>O regime cadastral não aplica alíquotas automaticamente. As regras são configuradas e conferidas por vigência.</span></div></div>
<div v-show="tab==='address'"><LookupAssist :target="form" kind="cep"/><div class="section-label">Localização do estabelecimento</div><div class="form-grid three"><label>CEP<input v-model="form.postal_code" maxlength="9" placeholder="00000-000"/></label><label class="span-2">Logradouro<input v-model="form.address" placeholder="Rua, avenida ou praça"/></label><label>Número<input v-model="form.number"/></label><label class="span-2">Bairro<input v-model="form.district"/></label><label>UF<select v-model="form.state"><option value="">Selecione</option><option v-for="uf in 'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ')" :key="uf">{{uf}}</option></select></label><label>Município<input v-model="form.city"/></label><label>Código IBGE<input v-model="form.ibge" maxlength="7" inputmode="numeric"/></label></div></div>
<div v-show="tab==='fiscal'"><div class="section-label">Inscrições e atividade</div><div class="form-grid three"><label>Inscrição estadual<input v-model="form.ie" placeholder="Número ou ISENTO"/></label><label>Inscrição municipal<input v-model="form.im"/></label><label>CNAE principal<input v-model="form.cnae" placeholder="0000-0/00"/></label></div><RegistrationProfile :model="form.profile"/><div class="info-card"><Icon name="settings"/><div><strong>Parametrização por empresa e vigência</strong><p>CFOP, NCM, receitas, serviços e regras ficam em Parâmetros. Mantenha a fonte e o responsável pela conferência de cada regra.</p></div></div></div>
<div v-show="tab==='accounting'"><div class="section-label">Plano de contas</div><label v-if="!editing" class="choice-card"><input type="checkbox" v-model="form.create_default_accounts"/><div><strong>Criar plano inicial editável</strong><small>Contas básicas para começar. Revise a estrutura antes de usar na escrituração da empresa. Não inclui regras fiscais.</small></div></label><div v-else class="info-card"><Icon name="book"/><div><strong>Plano de contas e centros de custo</strong><p>Gerencie as contas na guia Contabilidade. Alterar este cadastro não transfere movimentos nem modifica a empresa ativa.</p></div></div></div>
<div v-show="tab==='integrations'"><div class="section-label">Integração com o sistema de referência</div><div class="form-grid"><label>Código da empresa na Prosoft<input v-model="form.prosoft_code" placeholder="Código de correspondência"/><small>Identificação para mapeamento; não envia dados.</small></label></div><div class="message warning"><Icon name="alert"/><span>Exportação para a Prosoft depende de perfil de leiaute validado e conferência dos totais na instalação de destino.</span></div></div>
</form><template #footer><span class="footer-hint"><Icon name="shield" :size="15"/>{{editing?'Alterações ficam no histórico do cadastro.':'Campos marcados com * são obrigatórios.'}}</span><div class="actions"><button class="button" @click="close" :disabled="busy">Cancelar</button><button v-if="!editing" class="button outline" type="button" @click="save(true)" :disabled="busy">Salvar e ativar</button><button class="button primary" form="company-form" type="submit" :disabled="busy"><Icon :name="busy?'loading':'check'"/>Salvar empresa</button></div></template></BaseModal>
</div></template>
